import java.util.Scanner;

public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    String S = sc.next();
    int sLength = S.length();
    for (int i = 0; i < sLength; i++) {
        char ch = S.charAt(i);
        int cnt = 0;
        for (int j = 0; j < sLength; j++) {
            if (S.charAt(j) == ch) {
                cnt++;
            }
        }
        if (cnt == 1) {
            System.out.println(i);
            return;
        }
    }
}
